// Flatten both chunk files, then group by collection into embedding batches of 16 texts
const COLL = { A: 'regs_fixed', B: 'regs_structured' };
const chunks = $input.all().flatMap(it => Array.isArray(it.json.data) ? it.json.data : (Array.isArray(it.json) ? it.json : []));
const out = [];
for (const s of ['A', 'B']) {
  const cs = chunks.filter(c => c.strategy === s);
  for (let i = 0; i < cs.length; i += 16) {
    const b = cs.slice(i, i + 16);
    out.push({ json: {
      collection: COLL[s],
      ids: b.map(c => c.point_id),
      texts: b.map(c => c.text),
      payloads: b.map(c => ({ chunk_id: c.chunk_id, strategy: c.strategy, doc_id: c.doc_id, doc_title: c.doc_title,
        doc_status: c.doc_status, regime: c.regime, regimes: c.regimes, article_keys: c.article_keys,
        page_start: c.page_start, page_end: c.page_end, text: c.text })),
    } });
  }
}
if (!out.length) throw new Error('no chunks read from /data/index/chunks_*.json');
return out;

// Pair each batch with its embeddings (same item index), then one upsert body per collection
const batches = $('Batches of 16').all();
const by = {};
$input.all().forEach((it, i) => {
  const b = batches[i].json, vecs = it.json.embeddings;
  if (!vecs || vecs.length !== b.ids.length) throw new Error(`batch ${i}: ${vecs ? vecs.length : 0} vectors for ${b.ids.length} texts`);
  by[b.collection] = by[b.collection] || [];
  b.ids.forEach((id, k) => by[b.collection].push({ id, vector: vecs[k], payload: b.payloads[k] }));
});
return Object.entries(by).map(([collection, points]) => ({ json: { collection, points, n: points.length, dims: points[0].vector.length } }));

// One log line per collection: chunks sent, points counted in Qdrant, vector size
const sent = $('Points per collection').all();
return $input.all().map((it, i) => ({ json: { collection: sent[i].json.collection, chunks_sent: sent[i].json.n,
  points_in_qdrant: it.json.result.count, dims: sent[i].json.dims, ok: it.json.result.count === sent[i].json.n,
  finished_at: new Date().toISOString() } }));
